41	/// Recurse through all subregions and all regions and add them to RQ.
42	static void addRegionIntoQueue(Region &R, SmallVector<Region *> &RQ) {
43	  RQ.push_back(&R);
44	  for (const auto &E : R)
45	    addRegionIntoQueue(*E, RQ);
46	}
